<!-- ADP / Agent chat workspace. Vue 3. No external UI dependencies.
     AI responses and workflow runs are local interactions; connect your own services.
     Listen for adp-navigate on the root to integrate your application router. -->
<script setup>
import { ref, onMounted, onBeforeUnmount } from 'vue';
const root = ref(null);
let cleanup;
onMounted(() => { cleanup = mountDemo(root.value); });
onBeforeUnmount(() => cleanup?.());
function mountDemo(root) {
  const cleanups = [];
  const timers = new Set();
  const intervals = new Set();
  const document = {
    querySelector: (s) => root.querySelector(s),
    querySelectorAll: (s) => root.querySelectorAll(s),
    createElement: (tag) => window.document.createElement(tag),
    addEventListener: (name, handler) => { root.addEventListener(name, handler); cleanups.push(() => root.removeEventListener(name, handler)); },
  };
  const setTimeout = (fn, ms) => { const id = window.setTimeout(() => { timers.delete(id); fn(); }, ms); timers.add(id); return id; };
  const setInterval = (fn, ms) => { const id = window.setInterval(fn, ms); intervals.add(id); return id; };
  const clearInterval = (id) => { window.clearInterval(id); intervals.delete(id); };
  
const $=s=>document.querySelector(s);const $$=s=>[...document.querySelectorAll(s)];
const t={"workspace":"Workspace","new":"New conversation","search":"Search conversations","overview":"Overview","chat":"Conversations","research":"Research","workflow":"Workflows","inbox":"Approvals","knowledge":"Knowledge","settings":"Settings","project":"PRODUCT / AUTUMN LAUNCH","share":"Share brief","ready":"Ready to collaborate","placeholder":"Ask a question, or give your agent a task…","attach":"Attach a file","send":"Send message","mode":"Reasoning mode","balanced":"Balanced","deep":"Deep research","fast":"Fast","sources":"Sources & context","activity":"Activity","context":"Project context","team":"Product team","members":"3 collaborators","brief":"Launch brief.md","guide":"Brand guidelines.pdf","updated":"Updated 12 min ago","suggest":"Suggested next steps","step1":"Review the positioning","step2":"Draft a launch checklist","step3":"Compare the alternatives","welcome":"Your next idea starts here.","intro":"A quiet space for ambitious work. Ask, explore, and make progress with an agent by your side.","chips":["Plan the next launch","Summarize my documents","Explore an idea"],"you":"You","agent":"Forma Agent","answer":"Let’s break that down. First, define the outcome and audience. Then list the constraints, compare two approaches, and choose one small next step.","copied":"Brief copied","file":"Attached","notice":"Connect an AI provider in your own project to generate live responses.","run":"Run workflow","running":"Running…","complete":"Run complete","runTitle":"A thoughtful workflow, end to end.","runIntro":"Turn a broad goal into a clear, reviewable sequence.","steps":["Read the project brief","Compare the source material","Draft the recommendation","Prepare a review checklist"],"pending":"Ready","done":"Complete","approve":"Approve","reject":"Request changes","approved":"Approved","rejected":"Changes requested","approvalTitle":"Decisions that deserve your attention.","approvalIntro":"Review what your agents propose before anything goes out.","approval":["Publish launch announcement","Update the product brief","Send the weekly digest"],"review":"Review proposal","risk":"Requires your approval","kbTitle":"Give your agent a place to learn.","kbIntro":"A considered collection of context, ready for your next question.","kbSearch":"Search your knowledge base","add":"Add document","documents":"Documents","noResults":"No documents match your search.","researchTitle":"A question worth exploring.","researchIntro":"From open questions to grounded decisions. Keep your evidence close.","researchQuery":"How should we position the autumn launch?","researchBody":"A focused launch gives the team room to tell one clear story. Lead with the problem your audience already knows, then make the first useful action obvious.","finding":"Working notes","finding1":"Clarity before features","finding2":"One audience, one promise","finding3":"Make the first step small","source1":"Product strategy · 4 pages","source2":"Customer interviews · 12 notes","source3":"Launch review · 3 decisions","empty":"Start a new thread","emptyCopy":"What would you like to work on?","offline":"Local preview","menu":"Toggle navigation","close":"Close context","openContext":"Open context","download":"Download brief"};
const shell=$('.agent-shell');
function note(s){$('.context-note').textContent=s;shell.classList.add('context-open')}
function ping(s){const el=$('.agent-toast');el.textContent=s;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),2500)}
$('.mobile-menu').onclick=()=>{$('.mobile-menu').setAttribute('aria-expanded',String(shell.classList.toggle('nav-open')))};
$('.context-toggle').onclick=()=>{$('.context-toggle').setAttribute('aria-expanded',String(shell.classList.toggle('context-open')))};
$('.context-close').onclick=()=>shell.classList.remove('context-open');
document.addEventListener('keydown',e=>{if(e.key==='Escape'){shell.classList.remove('nav-open','context-open');$('.mobile-menu').setAttribute('aria-expanded','false');$('.context-toggle').setAttribute('aria-expanded','false')}});
const composer=$('.agent-composer');
if(composer){composer.onsubmit=e=>{e.preventDefault();const input=$('#agent-input');const value=input.value.trim();if(!value){input.focus();return}const messages=$('.agent-messages');for(const [who,body] of [[t.you,value],[t.agent,t.answer]]){const msg=document.createElement('div');msg.className='message'+(who===t.you?' user':'');const name=document.createElement('b');name.textContent=who;const content=document.createElement('span');content.textContent=body;msg.append(name,content);messages.append(msg)}input.value='';messages.lastElementChild.scrollIntoView({behavior:'smooth',block:'nearest'})};$('#agent-attach').onclick=()=>$('#agent-file').click();$('#agent-file').onchange=()=>$('#agent-filename').textContent=$('#agent-file').files[0]?.name||'';}
$$('[data-suggestion]').forEach(b=>b.onclick=()=>{const input=$('#agent-input');if(input){input.value=t.chips[+b.dataset.suggestion];input.focus()}else note(b.textContent.trim()+'\n\n'+t.answer)});
$$('[data-citation]').forEach(b=>b.onclick=()=>note([t.brief,t.guide][+b.dataset.citation]+'\n\n'+t.researchBody));
$('.new-thread').onclick=()=>{if($('.agent-messages')){$('.agent-messages').replaceChildren();$('#agent-input').value='';$('#agent-input').focus()}else note(t.emptyCopy);shell.classList.remove('nav-open')};
$$('[data-agent-nav]').forEach(b=>b.onclick=()=>{shell.dispatchEvent(new CustomEvent('adp-navigate',{bubbles:true,detail:{kind:b.dataset.agentNav}}));if(b.dataset.agentNav!==shell.dataset.kind)ping(t[b.dataset.agentNav]+' — '+t.notice)});
$$('[data-project]').forEach(b=>b.onclick=()=>{$$('[data-project]').forEach(x=>x.classList.toggle('selected',x===b));$('.agent-breadcrumb').textContent=(t.project.includes('产品')?'项目 / ':'PROJECT / ')+b.textContent.trim();shell.classList.remove('nav-open')});
$('.settings-toggle').onclick=()=>{let el=$('.agent-settings');if(el){el.remove();return}el=document.createElement('div');el.className='agent-settings';el.textContent=t.notice;$('.agent-sidebar').append(el)};
$('#agent-share').onclick=()=>{const blob=new Blob([t.project+'\n\n'+t.researchBody],{type:'text/plain'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='project-brief.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);ping(t.download)};
if($('#run-agent')){$('#run-agent').onclick=()=>{const b=$('#run-agent');b.disabled=true;b.textContent=t.running;$('#run-status').textContent=t.running;let i=0;const finish=()=>{const row=$$('.agent-steps li')[i];row.classList.add('done');row.querySelector('.step-number').textContent='✓';row.querySelector('.step-status').textContent=t.done;i++;if(i<4){setTimeout(finish,450)}else{$('#run-status').textContent=t.complete;b.textContent=t.complete;$('.run-output').hidden=false;$('.run-output').textContent=t.researchBody}};setTimeout(finish,350)}}
$$('[data-approve],[data-reject]').forEach(b=>b.onclick=()=>{const card=b.closest('.approval-card');card.classList.add('resolved');card.querySelector('.approval-status').textContent=b.hasAttribute('data-approve')?t.approved:t.rejected;card.querySelectorAll('button').forEach(x=>x.disabled=true)});
if($('#kb-search')){$('#kb-search').oninput=e=>{let count=0;$$('.document-row').forEach(row=>{row.hidden=!row.textContent.toLowerCase().includes(e.target.value.toLowerCase());if(!row.hidden)count++});$('#kb-empty').hidden=count>0};$('#kb-add').onclick=()=>$('#kb-file').click();$('#kb-file').onchange=()=>{const f=$('#kb-file').files[0];if(!f)return;const row=document.createElement('button');row.className='document-row';const icon=document.createElement('span');icon.className='doc-icon';icon.textContent='FILE';const label=document.createElement('span');const name=document.createElement('b');name.textContent=f.name;const meta=document.createElement('small');meta.textContent=(f.size/1024).toFixed(1)+' KB';label.append(name,meta);row.append(icon,label);row.onclick=()=>{const panel=$('.document-preview');panel.hidden=false;panel.textContent=f.name+'\n'+t.file};$('.document-list').append(row);$('#kb-search').value='';$('#kb-search').dispatchEvent(new Event('input'))};$$('[data-doc]').forEach(b=>b.onclick=()=>{const p=$('.document-preview');p.hidden=false;p.textContent=b.querySelector('b').textContent+'\n\n'+t.researchBody})}
;document.querySelector('.agent-shell').addEventListener('adp-navigate',e=>parent.postMessage({type:'adp-navigate',kind:e.detail.kind},'*'));
  return () => { timers.forEach(window.clearTimeout); intervals.forEach(window.clearInterval); cleanups.forEach(fn => fn()); };
}
</script>

<template>
  <div ref="root" class="adp-agent-chat"><div class="agent-shell" data-kind="chat"><aside class="agent-sidebar"><a class="agent-brand" href="#"><span>f</span> forma<span class="agent-brand-dot">.</span></a><button class="new-thread">＋ New conversation<kbd>⌘ N</kbd></button><div class="sidebar-label">Workspace</div><nav aria-label="Workspace"><button data-agent-nav="chat" class="active"><span class="nav-symbol">◈</span><span>Conversations</span></button><button data-agent-nav="research" class=""><span class="nav-symbol">⌕</span><span>Research</span></button><button data-agent-nav="workflow" class=""><span class="nav-symbol">⌘</span><span>Workflows</span></button><button data-agent-nav="inbox" class=""><span class="nav-symbol">▤</span><span>Approvals</span><small>3</small></button><button data-agent-nav="knowledge" class=""><span class="nav-symbol">▧</span><span>Knowledge</span></button></nav><div class="sidebar-projects"><span class="sidebar-label">PROJECTS</span><button data-project="Autumn launch"><i style="background:#8f9f72"></i>Autumn launch</button><button data-project="Brand direction"><i style="background:#b597cb"></i>Brand direction</button><button data-project="Product roadmap"><i style="background:#d5a06c"></i>Product roadmap</button></div><div class="agent-profile"><span>JD</span><div><b>Jamie Davis</b><small>Personal workspace</small></div><button class="settings-toggle" aria-label="Settings">⚙</button></div></aside><div class="agent-workarea"><header class="agent-header"><button class="mobile-menu" aria-label="Toggle navigation">☰</button><span class="agent-breadcrumb">PRODUCT / AUTUMN LAUNCH</span><div><span class="collaborators"><i>JD</i><i>AL</i><i>MK</i></span><button id="agent-share">Share brief ↗</button><button class="context-toggle" aria-label="Open context">◫</button></div></header><div class="agent-center"><main class="agent-main"><div class="agent-intro"><span class="agent-kicker">FORMA / CONVERSATIONS</span><h1>Your next idea starts here.</h1><p>A quiet space for ambitious work. Ask, explore, and make progress with an agent by your side.</p></div><div class="suggestions"><button data-suggestion="0">↗ <span>Plan the next launch</span></button><button data-suggestion="1">▧ <span>Summarize my documents</span></button><button data-suggestion="2">✳ <span>Explore an idea</span></button></div><div class="agent-messages" aria-live="polite"></div></main><form class="agent-composer"><textarea id="agent-input" aria-label="Ask a question, or give your agent a task…" placeholder="Ask a question, or give your agent a task…" rows="2"></textarea><div><button type="button" id="agent-attach" aria-label="Attach a file">＋</button><input type="file" id="agent-file" hidden><span id="agent-filename"></span><select id="agent-model" aria-label="Reasoning mode"><option>Balanced</option><option>Deep research</option><option>Fast</option></select><button class="agent-primary" aria-label="Send message" type="submit">↑</button></div></form><div class="agent-bottom"><span class="agent-status-dot"></span><span>Forma Agent · Ready to collaborate</span><span class="local-status">Local preview</span></div></div></div><aside class="agent-context"><div class="context-heading"><b>Project context</b><button class="context-close" aria-label="Close context">✕</button></div><div class="context-section"><label>Sources & context</label><button class="source-file" data-citation="0"><span>▧</span><div><b>Launch brief.md</b><small>Markdown · 12 KB</small></div><span>↗</span></button><button class="source-file" data-citation="1"><span>▧</span><div><b>Brand guidelines.pdf</b><small>PDF · 246 KB</small></div><span>↗</span></button></div><div class="context-section"><label>Suggested next steps</label><button class="next-step" data-suggestion="0"><span>Review the positioning</span>↗</button><button class="next-step" data-suggestion="1"><span>Draft a launch checklist</span>↗</button><button class="next-step" data-suggestion="2"><span>Compare the alternatives</span>↗</button></div><div class="context-section"><label>Activity</label><div class="activity-line"><i></i><div>Ready to collaborate<small>Updated 12 min ago</small></div></div></div><div class="context-note" aria-live="polite"></div><div class="context-team"><span class="collaborators"><i>JD</i><i>AL</i><i>MK</i></span><div><b>Product team</b><small>3 collaborators</small></div></div></aside><div class="agent-toast" role="status"></div></div></div>
</template>

